import{_ as t}from"./chunks/43f2931a288dc9c56fb5.BH2pqIgW.js";import{_ as a,C as l,o,c as i,j as e,a as s,E as n,a5 as h}from"./chunks/framework.DNkHA0lr.js";const q=JSON.parse('{"title":"微型教育企业是未来（零成本起步）","description":"","frontmatter":{"title":"微型教育企业是未来（零成本起步）","originalTitle":"Micro Education Businesses Are The Future (Zero Dollars To Start)","date":"2023-09-02","originalUrl":"https://thedankoe.com/letters/why-micro-education-businesses-are-the-future-zero-dollars-to-start/","minutes":13,"sourceHash":"d10802dffa2da2e3cb552a152e8401c12a1ee14033701ca014c223c1e5b2ebe4","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/why-micro-education-businesses-are-the-future-zero-dollars-to-start/"}]]},"headers":[],"relativePath":"letters/why-micro-education-businesses-are-the-future-zero-dollars-to-start.md","filePath":"letters/why-micro-education-businesses-are-the-future-zero-dollars-to-start.md"}'),u={name:"letters/why-micro-education-businesses-are-the-future-zero-dollars-to-start.md"};function d(c,p,m,g,f,b){const r=l("ArticleMeta");return o(),i("div",null,[p[0]||(p[0]=e("h1",{id:"微型教育企业是未来-零成本起步",tabindex:"-1"},[s("微型教育企业是未来（零成本起步） "),e("a",{class:"header-anchor",href:"#微型教育企业是未来-零成本起步","aria-label":'Permalink to "微型教育企业是未来（零成本起步）"'},"​")],-1)),n(r),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/6XSim-zigGA?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我正在建立一家软件公司。</p><p>但我采取了不同的方法。</p><p>常见的路线是构建产品，对其进行测试，然后向特定的受众进行营销。</p><p>这行得通，但我想跳过这项业务“成败在此一举”的阶段。</p><p>我非常清楚，客户流失、开发人员成本以及将软件融入人们的日常生活中将是困难重重的。</p><p>相反，我计划在第一年将公司的营收做到500万到1000万美元。</p><p><em>（2024年2月2日编辑：我们正朝着这个目标稳步前进）</em></p><p>是个远大的目标，没错。</p><p>但怎么做呢？</p><p>通过利用我在现代商业中积累的经验。</p><p>我知道个人品牌的威力。我知道数字产品的威力（以及为什么一家1000万美元的数字产品企业比大多数5000万美元的实体产品企业更有利可图）。我知道我可以利用这两者创造一款教育产品，作为我们开业第一年收入的主要驱动力——并且该产品的利润率能高达95%。</p><p>我们将像打造个人品牌一样来打造公司的社交媒体——用一个“化身”作为品牌的门面。大多数企业根本不知道建立真正的社交媒体受众需要付出什么，所以他们依赖于创作者赞助。我们要创造一个创作者。</p><p>我们将利用这批受众，以及大量创作者的受众，来推动一门围绕我们软件主题的同期群课程。</p><p>到那时，软件本身在第一年是否盈利就不重要了。我们可以放眼长远，将其慢慢注入创作者经济中，成为唯一真正的第二大脑软件。</p><p>但是，这封信不是关于软件的。</p><p>它关乎的是<em>你如何利用头脑中的知识，启动一家超高利润的教育企业。</em></p><p>你不需要为了让这一切奏效去开发软件。</p><p>当然，你可以围绕你所销售的盈利性教育产品来开发软件，以此提升你的商业成果（如果你未来想这么做的话——因为到时你会有钱去投资开发）。</p><p>以下是你可以期待的内容：</p><ol><li>为什么社交媒体受众是最高杠杆的商业资产。</li><li>如何<em>创造</em>你自己的客户（而不是试图用无聊的市场调查去“寻找”他们）。</li><li>意识到你脑子里藏着10万美元（以及如何将它提取出来）。</li></ol><p>如果你想了解关于未来工作的完整理念，请在亚马逊上购买 <a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">《专注的艺术》（The Art of Focus）一书</a>。</p><h2 id="建立受众是这十年来最伟大的技能" tabindex="-1">建立受众是这十年来最伟大的技能 <a class="header-anchor" href="#建立受众是这十年来最伟大的技能" aria-label="Permalink to &quot;建立受众是这十年来最伟大的技能&quot;">​</a></h2><p>个人品牌是不会消亡的新浪潮。</p><p>妈，这可不是三分钟热度。</p><p>数字世界的扩张速度快于物理世界，而个人品牌就是占据这个空间的化身。</p><p>每个人都有个人品牌。每个人都身处创作者经济之中。但很少有人意识到，他们的贡献（发帖和产品）根本算不上什么贡献。</p><p>消费者们正忙着发布生活日常，试图给那些算不上真正朋友的“朋友”留下深刻印象。</p><p>创作者正在学习、构建并提炼有价值的信息，让每个人的生活变得更好。</p><h3 id="认识到自有分发的价值" tabindex="-1">认识到自有分发的价值 <a class="header-anchor" href="#认识到自有分发的价值" aria-label="Permalink to &quot;认识到自有分发的价值&quot;">​</a></h3><p><img src="'+t+'" alt=""></p><p>我结识并关注了许多高层级的企业家。</p><p>有些从事私募股权，有些从事代理业务，还有些从事软件或相关领域。</p><p>几乎在我们的每一次谈话中，都会提到自有分发这一点。</p><p>“我不知道为什么自己没有早点开始发布内容。”</p><p>“营销世界在短短几年内发生的改变太疯狂了，个人品牌越来越成为一种必需而非可有可无的选择了。”</p><p>当然，这并不消除对其他类型分发渠道的需求：</p><ol><li><strong>手动分发</strong> —— 比如冷邮件、冷电话或直接私信开发活动。</li><li><strong>购买分发</strong> —— 比如购买Facebook或谷歌广告。</li><li><strong>借用分发</strong> —— 比如付费赞助播客、YouTube或新闻通讯。</li><li><strong>自有分发</strong> —— 比如建立受众群体、新闻通讯、社区或产品买家名单。</li></ol><p>它们之间的界限有些模糊，而且我还漏掉了一些比如SEO这样的东西，但它们都有各自的用武之地。</p><p>前3种对于测试、初学者企业主以及对结果保留某种形式的控制权来说，是非常棒的。</p><p>自有分发是一场吓退了大多数人的长期游戏。</p><p>让我们设想一下，我花了2年时间建立了一个10万人的受众群体。</p><p>如果我每天推广我的产品长达一个月（以一种聪明的方式），我至少能获得100万次曝光。</p><p>我需要多长时间才能给100万人发私信？需要很久。</p><p>我需要花多少钱才能通过广告触达那么多人？大概每个月7000美元（按7美元的平均千人成本计算）。</p><p>更不用说，自有分发具有复利效应。</p><p>你可以在一年内获得1到2万名粉丝，在两年内达到5到10万，在4到5年后达到数百万。前提是，如果你知道如何迭代你最优秀的内容……或者甚至你得先知道怎么写内容。</p><p>只有随着时间的推移<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">系统化你的受众增长</a>并利用其他分发渠道的杠杆来赚取你渴望的收入，才是合理的。</p><p>一旦你看到了个性的力量、自有分发的威力，以及个人品牌的灵活性——你就回不去了。</p><h3 id="建立受众是一系列高价值技能的叠加" tabindex="-1">建立受众是一系列高价值技能的叠加 <a class="header-anchor" href="#建立受众是一系列高价值技能的叠加" aria-label="Permalink to &quot;建立受众是一系列高价值技能的叠加&quot;">​</a></h3><p>要想成为一名优秀的受众建设者，你不能仅仅学习“受众建设”。</p><p>大多数能获得超常回报的技能都是如此。</p><p>这绝不像找个“2023年最值得学习的技能”的视频来看看那么简单，因为其他人都在这么做。这是让你自己商品化且变得可替代的绝佳捷径。</p><p>建立受众是当今最赚钱的一系列技能的叠加：</p><ul><li>平面设计</li><li>内容写作</li><li>文案写作</li><li>营销与销售</li><li>人性</li><li>心理学</li><li>自我认知</li><li>人脉网络</li></ul><p>而且它要求跨学科的学习和专业知识。</p><p>建立受众是一种<em>生活方式</em>。</p><p>它是以能够影响积极行为改变的方式，来捕捉、策展、连接、创造并分发有价值的信息、资源和产品的行为。</p><p>如果你不去追求更好的生活，你就会失败。</p><p><em>更好的生活需要学习、构建和分发的习惯。</em></p><h3 id="开始学习、构建与分发的快速提示" tabindex="-1">开始学习、构建与分发的快速提示 <a class="header-anchor" href="#开始学习、构建与分发的快速提示" aria-label="Permalink to &quot;开始学习、构建与分发的快速提示&quot;">​</a></h3><p>以下正是你必须做的（没有废话）。</p><p>这些必须成为习惯。</p><p>这意味着要成为你日常生活的一部分。</p><p>如果你能花8小时去构建别人的梦想，你就能花1小时来构建你自己的梦想。</p><p>如果你连每天花1小时去投资以换取未来的每天2小时（以此类推）都没有，那你需要理清自己的优先级了。</p><p><strong>带着意图去学习：</strong></p><p>学习营销、销售、写作和社交媒体的原理。疯狂刷个30-50小时的免费内容和付费课程。在这个过程中建立你的个人品牌，这样你才能真正应用你所学到的知识。</p><p>研究让你感兴趣的东西。不要限制自己。如果你的目标是为自己打造更好的生活，你学到的任何东西都将从那个视角出发。你依然是在“专注于一件事”。</p><p>当你感受到发现新想法带来的兴奋或多巴胺时，把它写下来。完善那个想法，然后将它发布到你的主页上。</p><p><strong>为你自己而构建：</strong></p><p>追求你的目标并记录整个过程。我说的记录，是指在一个安全的地方（无论是实体的还是数字的）持续保存笔记、日志、成功和失败的经验。</p><p>从你的旅程中，你获得了100分的知识。基于此，你可以开辟出1条路径。这就是你如何传承一个自带营销属性的独特系统，并取得比那些只想赚快钱的人更好的结果。</p><p>在这条路上，发布你经历过的建议、教训以及真实的成功与失败。这被称为“公开构建”。不要为了别人去这么做，把它当成一份数字日记。它会带来回报的。</p><p><strong>分发有目的性的产品：</strong></p><p>大多数人没有意识到产品是权威的催化剂。他们认为通过卖产品是在“出卖灵魂”，却不知道这能为他们的品牌增加感知权威，并且他们会获得更多忠实的追随者。</p><p>创造一款你在生活中需要（或者曾经需要）的产品。一种本可以帮助你达到现在位置的东西，或者一种能帮你更快实现某个目标的东西。这可以是展现风格的衣服、传授知识的课程、提升生产力的手帐，或者是介于两者之间的任何东西。</p><p>卖给你自己，你就不用担心竞争了。</p><h2 id="通过教育创造客户" tabindex="-1">通过教育创造客户 <a class="header-anchor" href="#通过教育创造客户" aria-label="Permalink to &quot;通过教育创造客户&quot;">​</a></h2><p>我不认同市面上99%商业大师的观点。</p><p>大多数取得了巨大成功的人都老了，与时代脱节了。而大多数年轻人从不质疑老一辈的话，也从未开辟出一条新路。</p><p>常见的建议是“为一个极度饥渴的市场打造产品，然后把那个市场吸引过来作为你的受众。”</p><p>是的，这显然行得通。</p><p>但它也伴随着以下缺点：</p><ul><li>讨厌你的客户群，并且感到没有动力去工作。</li><li>对你写什么、构建什么没有自主权。</li><li>无法转型到你好奇的任何话题或兴趣上。</li><li>被迫困在一个特定的身份中，而这会波及到你生活的方方面面。</li></ul><p>当你通过课程、内容、同期群和辅导（全都是可选的）在你的品牌中优先考虑教育时，你就解锁了<em>创造</em>你自己客户的能力。</p><h3 id="人类是学习机器" tabindex="-1">人类是学习机器 <a class="header-anchor" href="#人类是学习机器" aria-label="Permalink to &quot;人类是学习机器&quot;">​</a></h3><p>为什么一个极度饥渴的市场会渴望他们所渴望的东西？</p><p>为什么他们愿意掏出信用卡，为他们认为有价值的东西买单？</p><p>为什么有人会告诉你必须“深耕细分领域”，以便你能在营销中具体说明你要利用的杠杆问题？</p><p>因为社会化条件反射、学习和教育。</p><p>你瞄准一个特定的人，是因为他们被教育成了拥有那种身份。</p><p>他们的身份影响着他们的渴望（因为他们所结交的圈子，以及他们眼中的机会）。</p><p>当你通过教育来<em>创造</em>身份，用你的叙事引导人们走向你的愿景时，人们就会逐渐渴望那个能帮他们达成目标的商品。</p><h3 id="认知的层级" tabindex="-1">认知的层级 <a class="header-anchor" href="#认知的层级" aria-label="Permalink to &quot;认知的层级&quot;">​</a></h3><p>有一个名为“认知层级”的营销概念将会改变你的一生。</p><p>它是尤金·施瓦茨（Eugene Schwartz）在其著作<em>《突破广告》（Breakthrough Advertising）</em>中普及开来的一个简单的文案框架。</p><p>它不仅适用于营销，而且适用于一切事物。</p><p>进化是为了解决宏观世界中的问题。个人成长是为了解决微观世界中的问题。而商业则是解决问题，以弥合两者之间的差距。</p><p>商业就是你对人类的贡献。</p><p>它也是你如何去实现提升个人意识（或认知）的人生目标，并让这种意识像水波一样影响世界的方式。</p><p>认知有5个层级：</p><ul><li><strong>无认知</strong> —— 意识不到问题的存在。</li><li><strong>问题认知</strong> —— 意识到问题所在。</li><li><strong>方案认知</strong> —— 意识到有一个或多个解决问题的方法。</li><li><strong>产品认知</strong> —— 意识到你是如何解决这个问题的方案。</li><li><strong>最高认知</strong> —— 意识到那个问题对他们的生活质量正产生着巨大的影响。</li></ul><p>作为一家教育品牌，你的工作就是覆盖所有这些层级。</p><p>你必须让受众意识到你曾在生活中解决过的问题（以及这个问题如何影响他们的生活）。</p><p>你必须提供建议、经验和技巧，向他们展示解决方案是存在的。</p><p>你必须营销一款产品，凭借用户倾注的注意力，它能更快地解决这个问题。</p><p>人们登录社交媒体并不是为了解决问题。那不是一个学习平台。而且大多数人无法专注、研究并为自己摸索出一条道路。</p><p>这就是产品之所以有价值的原因。</p><p>因为人们知道自己是在投资一个解决方案。然后，他们的注意力和行为就会随之改变。</p><p>免费教育只对那1%习惯于保持动力和野心的人有效。即使是他们，依然能看到信息聚合的价值，并且很可能会为了方便而购买产品。</p><h3 id="长内容与短内容的平衡" tabindex="-1">长内容与短内容的平衡 <a class="header-anchor" href="#长内容与短内容的平衡" aria-label="Permalink to &quot;长内容与短内容的平衡&quot;">​</a></h3><p>对于初学者来说，主要有两种类型的内容（和交流方式）。</p><ul><li><strong>长内容</strong> – 播客、视频、文章、通讯（newsletters）、对谈、电影，有时也包括像长推文（threads）这样的长篇社交帖子。</li><li><strong>短内容</strong> – 推文（tweets）、短视频（shorts、reels）、短信、电子邮件、大想法，以及你最喜欢的名言。</li></ul><p>两者各有优缺点，但从长远来看，为了建立一个<em>信任</em>你的受众群体，它们都是必不可少的。信任是人们开始意识到的“新”销售技巧。</p><p>短内容用于吸引注意力、建立庞大的受众群体，并将这些受众引流到更深层次的价值源泉（长内容平台、产品和服务）。</p><p>长内容用于维持倾注的注意力、细分你的受众，并通过专业知识建立信任。</p><p>两者的平衡迫使你必须提供价值。如果你没有自我教育、构建产品或系统，以及用写作来理清思路和想法的习惯——你只是在拖延必然的结局。</p><p>我知道我的大多数读者都是初学者。</p><p>对于你，我建议从一个长内容渠道和一个短内容渠道开始。</p><p>最终，当你全职做这件事并将你的流程系统化时，你就可以将它们重新打包分发到所有平台。</p><p>对于长内容，我推荐做通讯。为什么？</p><ul><li>你可以在无人关注的时候练习。</li><li>你可以建立一个内容数据库，将其改写成博客、YouTube视频和单口播客。</li><li>长内容能与受众建立深度和连接，这样你就不用靠咄咄逼人的推销手段谋生了。</li><li>你被迫去发展原创观点，而这些观点会溢出到你的短内容中。</li></ul><p>对于短内容，我推荐像X这样的写作平台。为什么？</p><ul><li>你不<em>一定</em>非要露脸或露身材（当然，用头像作为个人资料图片会有帮助）。</li><li>你学会了将大脑变现，而不是靠长相变现。你的收入取决于你的创造力。</li><li>你每天可以测试多个想法，并将最好的想法分发到Instagram和LinkedIn等其他平台以实现更快的增长。</li><li>你可以把你的文字当作Shorts、Reels和TikToks的脚本。</li></ul><p>我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">两小时写手（2 Hour Writer）</a>中教授了整个流程。</p><p>从每天早上写30分钟开始。</p><p>写一篇长通讯。把你写过的观点作为短帖子。最终，让你的互动数据成为你进一步写作方向的指南针。</p><h2 id="你脑子里困着100-000美元" tabindex="-1">你脑子里困着100,000美元 <a class="header-anchor" href="#你脑子里困着100-000美元" aria-label="Permalink to &quot;你脑子里困着100,000美元&quot;">​</a></h2><p>我写了一整篇长文，关于如何打包<a href="/letters/you-have-100000-of-knowledge-trapped-in-your-brain">你脑子里的知识来创造一个价值10万美元的产品</a>。如果你在读完这篇长文后还意犹未尽，去读读那篇吧。</p><p>首先，让我们来处理大众对信息产品的首要反对意见：</p><p>“这不是实物。”</p><p>“它不可触摸。”</p><p>“它只是屏幕上的几个字。”</p><p>如果你存在的根基（以及你的生活质量）是你的大脑，而你的大脑是一台信息处理机器，且你消费的信息深刻影响着你人生的最终归宿（以及你所影响的他人的生活）——那么信息产品就是一个人能卖的最伟大的产品。</p><p>任何告诉你其他答案的人，要么没有想清楚，要么没有体验过这种商业模式。他们被自己最喜欢的大师的世界观所制约，无法自拔。</p><p>我越来越相信，每一个企业都应该有教育的<em>基础</em>。</p><p>每一个企业都应该有一款信息产品，以便大规模地传播积极的行为改变。</p><p>更不用说，它们拥有95%+的利润率，这标志着经济将继续青睐教育市场。技术和进化把我们带到了这一步，你又有什么资格去质疑大自然呢？</p><h3 id="如何消除一切市场饱和" tabindex="-1">如何消除一切市场饱和 <a class="header-anchor" href="#如何消除一切市场饱和" aria-label="Permalink to &quot;如何消除一切市场饱和&quot;">​</a></h3><p>为过去的自己或现在的自己打造一款产品。</p><p>一款能加速迈向有意义目标的进度的产品。</p><p>你的营销将围绕人类行为的普适原则展开：</p><ul><li><strong>目标（Purpose）</strong> – 一个促使人们走向更美好未来的极具说服力的理由。</li><li><strong>路径（Path）</strong> – 一个能为他们的行动带来清晰度的流程、系统或步骤。</li><li><strong>优先级（Priority）</strong> – 在他们的认知水平上面临的燃眉之急。</li></ul><p>如果你喜欢生产力，就创建一个工作流，并围绕它提供教育。</p><p>如果你喜欢灵性修行，就创作冥想内容，并围绕它提供教育。</p><p>如果你喜欢健身，就制定一个计划，并围绕它提供教育。</p><p>你无法改进不存在的东西，所以不要对最初的版本感到焦虑。这是一场关于改进的长期游戏。</p><p>“但是我的客户画像和市场调研怎么办？”</p><p>就是你自己。</p><p>你就是那个细分领域。</p><p>你就是那个客户画像。</p><p>写那些能打动你自己的内容和推销文案。</p><p>这里面有很多变动因素。你大概需要一年左右的时间，才能真正感觉自己摸到了门道。</p><p>但不要犯错，认为这是什么特殊情况。你在生活中做过的每一件事，都是一个不断试错的过程。</p><p>仅仅因为你年纪大了，心里建起了心理障碍，并不意味着你不能像当初学走路那样去建立一家企业。</p><p>朋友们，希望你们喜欢这篇文章。</p><p>祝周末愉快。</p><p>– 丹·柯（Dan Koe）</p><hr><p><a href="/en/letters/why-micro-education-businesses-are-the-future-zero-dollars-to-start">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',161))])}const P=a(u,[["render",d]]);export{q as __pageData,P as default};
